 static List<List<String>>deep(K k){List<List<String>>o=rows("cohort","sampleCount","edgeP50","edgeP90","edgeP95","edgeP99","gapP50","gapP90","gapP95","gapP99","modifierP50","modifierP90","ratioP50","ratioP90","baselineProbabilityP50","baselineProbabilityP90","candidateProbabilityP50","probabilityDeltaP50","probabilityDeltaP90","probabilityDeltaP95","randomMarginP50","randomMarginP90","riskP50","riskP90","timeP50","timeP90","blueCount","redCount","mechanisms");for(String c:List.of("UNCHANGED","CHANGED_CLOSE","CHANGED_MEDIUM","CHANGED_HIGH")){List<Obs>x=k.hold.stream().filter(v->cohort(v).equals(c)).toList();o.add(List.of(c,""+x.size(),f(val(x,v->Math.abs(v.edge),.5)),f(val(x,v->Math.abs(v.edge),.9)),f(val(x,v->Math.abs(v.edge),.95)),f(val(x,v->Math.abs(v.edge),.99)),f(val(x,v->Math.abs(v.gap),.5)),f(val(x,v->Math.abs(v.gap),.9)),f(val(x,v->Math.abs(v.gap),.95)),f(val(x,v->Math.abs(v.gap),.99)),f(val(x,v->Math.abs(v.mod),.5)),f(val(x,v->Math.abs(v.mod),.9)),f(val(x,v->v.gap==0?Double.NaN:Math.abs(v.mod/v.gap),.5)),f(val(x,v->v.gap==0?Double.NaN:Math.abs(v.mod/v.gap),.9)),f(val(x,v->v.bp,.5)),f(val(x,v->v.bp,.9)),f(val(x,v->v.cp,.5)),f(val(x,v->Math.abs(v.pdelta),.5)),f(val(x,v->Math.abs(v.pdelta),.9)),f(val(x,v->Math.abs(v.pdelta),.95)),f(val(x,v->v.margin,.5)),f(val(x,v->v.margin,.9)),f(val(x,v->v.risk,.5)),f(val(x,v->v.risk,.9)),f(val(x,v->v.time,.5)),f(val(x,v->v.time,.9)),""+n(x,v->v.side.equals("BLUE")),""+n(x,v->v.side.equals("RED")),x.stream().filter(v->v.flip).map(v->v.mech).distinct().collect(Collectors.joining("|"))));}return o;}
