 static K find(Review r,String k){return r.keys.stream().filter(x->x.key.equals(k)).findFirst().orElseThrow();}static String primary(Review r,ToLongFunction<Macro>f){return r.keys.stream().max(Comparator.comparingLong(k->f.applyAsLong(k.macro))).map(k->k.key).orElse("NONE");}static String cohort(Obs x){return x.flip?"CHANGED_"+x.localBand:"UNCHANGED";}static String db(double x,double a,double b){return x<=a?"NEAR":x>=b?"FAR":"MID";}static double axis(Obs x,String a){return switch(a){case"EDGE"->Math.abs(x.edge);case"GAP"->Math.abs(x.gap);case"RATIO"->x.gap==0?Double.NaN:Math.abs(x.mod/x.gap);case"PROBABILITY_DELTA"->Math.abs(x.pdelta);default->x.margin;};}static double vals(K k,boolean z,ToDoubleFunction<Obs>f,double p){return val(k.hold.stream().filter(x->x.flip==z).toList(),f,p);}static double val(List<Obs>x,ToDoubleFunction<Obs>f,double p){return q(x.stream().mapToDouble(f).boxed().toList(),p);}static long n(List<Obs>x,Predicate<Obs>p){return x.stream().filter(p).count();}static double rate(long n,long d){return d==0?0:(double)n/d;}static boolean fin(Double x){return x!=null&&Double.isFinite(x);}static String f(double x){return fin(x)?String.format(Locale.ROOT,"%.12f",x):"NOT_APPLICABLE";}static String key(Row r){return r.s("context")+"|"+r.s("actionType")+"|"+r.s("scoreDomain");}static double d(Row r,String k){return Double.parseDouble(r.s(k));}static boolean b(Row r,String k){return Boolean.parseBoolean(r.s(k));}
 static List<Row>read(Path p)throws IOException{List<String>x=Files.readAllLines(p,StandardCharsets.UTF_8),h=csv(x.getFirst());List<Row>o=new ArrayList<>();for(String l:x.subList(1,x.size()))if(!l.isBlank()){List<String>v=csv(l);Map<String,String>m=new HashMap<>();for(int i=0;i<h.size();i++)m.put(h.get(i),i<v.size()?v.get(i):"");o.add(new Row(m));}return o;}static List<String>csv(String l){List<String>o=new ArrayList<>();StringBuilder s=new StringBuilder();boolean q=false;for(int i=0;i<l.length();i++){char c=l.charAt(i);if(c=='"'){if(q&&i+1<l.length()&&l.charAt(i+1)=='"'){s.append('"');i++;}else q=!q;}else if(c==','&&!q){o.add(s.toString());s.setLength(0);}else s.append(c);}o.add(s.toString());return o;}static List<List<String>>rows(String...x){return new ArrayList<>(List.of(List.of(x)));}static void file(String n,List<List<String>>r)throws IOException{StringBuilder s=new StringBuilder();for(List<String>x:r){for(int i=0;i<x.size();i++){if(i>0)s.append(',');String v=x.get(i);if(v.contains(",")||v.contains("\"")||v.contains("\n"))s.append('"').append(v.replace("\"","\"\"")).append('"');else s.append(v);}s.append('\n');}Files.writeString(OUT.resolve(n),s,StandardCharsets.UTF_8);}static String sha(Path p)throws IOException{try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p)));}catch(Exception e){throw new IllegalStateException(e);}}static Map<Path,String>hashes()throws IOException{LinkedHashMap<Path,String>m=new LinkedHashMap<>();for(Path p:SOURCES)m.put(p,sha(p));return Map.copyOf(m);}static void verify()throws IOException{if(!sha(SOURCES.get(0)).equals(DSH)||!sha(SOURCES.get(1)).equals(DAH)||!sha(SOURCES.get(3)).equals(HSH)||!sha(SOURCES.get(4)).equals(HAH)||!FrozenCompositionGameplayGainPolicy.current().candidateHash().equals(FrozenCompositionGameplayGainPolicy.CANDIDATE_HASH))throw new IllegalStateException("source identity mismatch");}
 record Row(Map<String,String>v){String s(String k){if(!v.containsKey(k))throw new IllegalArgumentException("missing "+k);return v.get(k);}}record Obs(String key,String data,String side,double edge,double gap,double mod,double adjusted,String band,String localBand,boolean scoreFlip,boolean flip,String type,Double bp,Double cp,Double pdelta,Double margin,Double risk,String mech,int caseIndex,int time,String baseDecision,String candidateDecision){}record Dist(int count,double mean,double p10,double p25,double p50,double p75,double p90,double p95,double p99,double max,long zero){double at(double p){return p==.5?p50:p==.75?p75:p==.9?p90:p==.95?p95:p99;}}record Macro(long pub,long obj,long str,long win,long dur){static final Macro ZERO=new Macro(0,0,0,0,0);}static final class MB{long p,o,s,w,d;void add(boolean a,boolean b,boolean c,boolean e){p++;if(a)o++;if(b)s++;if(c)w++;if(e)d++;}Macro get(){return new Macro(p,o,s,w,d);}}record K(String key,List<Obs>dev,List<Obs>hold,Dist de,Dist he,Dist dg,Dist hg,Dist dm,Dist hm,Dist dr,Dist hr,String es,String gs,String ms,String rs,long flips,long high,long sd,long pc,long other,long unresolved,List<String>causes,String primary,String rec,Macro macro){}record Review(List<Obs>dev,List<Obs>hold,List<K>keys,Map<String,Macro>macro,Map<Path,String>before,Map<Path,String>after,boolean ok,String verdict,String next){}
